from pathlib import Pathimport jsonimport numpy as npimport pandas as pdimport matplotlib.pyplot as pltROOT = Path(__file__).resolve().parent.parentPROCESSED = ROOT / 'data' / 'processed'RESULTS = ROOT / 'results'RESULTS.mkdir(parents=True, exist_ok=True)PANEL = PROCESSED / 'multisat_2024_daily_decay_kp.csv'KP_FILE = PROCESSED / 'kp_daily_2024-04-01_to_2024-06-30.csv'MODEL_CSV = RESULTS / 'multisat_2024_model_comparison.csv'SLOPES_CSV = RESULTS / 'multisat_2024_kp_altitude_slopes.csv'FIGURE = RESULTS / 'multisat_2024_kp_altitude_model.png'PRED_CSV = RESULTS / 'multisat_2024_model_predictions.csv'TRAIN_END = pd.Timestamp('2024-05-15', tz='UTC')  # train May 1-14TEST_END = pd.Timestamp('2024-05-22', tz='UTC')   # test May 15-21START = pd.Timestamp('2024-05-01', tz='UTC')def prepare_data():    for file in (PANEL, KP_FILE):        if not file.exists():            raise FileNotFoundError(f'Missing {file}. Run analyze_multisat_2024.py / download_cirbe_kp.py first.')    data = pd.read_csv(PANEL)    data['date'] = pd.to_datetime(data['date'], utc=True, errors='coerce')    data['norad_id'] = pd.to_numeric(data['norad_id'], errors='coerce')    for col in ('altitude_km', 'decay_km_day'):        data[col] = pd.to_numeric(data[col], errors='coerce')    kp = pd.read_csv(KP_FILE, usecols=['date', 'daily_max_kp'])    kp['date'] = pd.to_datetime(kp['date'], utc=True)    kp['daily_max_kp'] = pd.to_numeric(kp['daily_max_kp'], errors='coerce')    kp = kp.drop_duplicates('date').sort_values('date')    # Align preceding day's Kp to the current day using actual calendar dates.    kp['kp_prev_day'] = kp['daily_max_kp'].shift(1)    data = data.drop(columns=['daily_max_kp'], errors='ignore').merge(        kp, on='date', how='left', validate='many_to_one'    )    data = data[(data.date >= START) & (data.date < TEST_END)].copy()    initial = len(data)    data = data.dropna(subset=['norad_id', 'date', 'altitude_km', 'decay_km_day', 'daily_max_kp', 'kp_prev_day'])    data['norad_id'] = data['norad_id'].astype(int)    # Exploratory screening, NOT verified maneuver detection: flag orbit raises    # >100m/day or unusual decay above 2km/day. Keep original data untouched.    data['excluded_possible_maneuver_or_outlier'] = (        (data.decay_km_day < -0.10) | (data.decay_km_day > 2.0)    )    exclusions = int(data.excluded_possible_maneuver_or_outlier.sum())    data = data[~data.excluded_possible_maneuver_or_outlier].copy()    data['period'] = np.where(data.date < TRAIN_END, 'train', 'test')    counts = data.groupby(['norad_id', 'period']).size().unstack(fill_value=0)    keep = counts.index[(counts.get('train', pd.Series(0, index=counts.index)) >= 8) &                        (counts.get('test', pd.Series(0, index=counts.index)) >= 3)]    data = data[data.norad_id.isin(keep)].copy()    # Altitude from training period only: no leakage from the test interval.    h = data[data.period == 'train'].groupby('norad_id').altitude_km.mean().rename('reference_altitude_km')    data = data.join(h, on='norad_id')    data['altitude_100km'] = (data.reference_altitude_km - 550.0) / 100.0    data['kp_centered'] = data.daily_max_kp - 3.0    data['kp_lag_centered'] = data.kp_prev_day - 3.0    print(f'Initial May records: {initial}; flagged/excluded suspicious changes: {exclusions}')    print(f'Usable observations: {len(data)}; satellites: {data.norad_id.nunique()}')    if data.norad_id.nunique() < 5:        raise RuntimeError('Too few satellites after filtering.')    return datadef fit_fixed_effects(train, feature_names):    """Within-satellite least squares with a per-satellite intercept."""    y = train['decay_km_day'].to_numpy(dtype=float)    ids = train['norad_id']    y_mean = train.groupby('norad_id').decay_km_day.mean()    x_means = train.groupby('norad_id')[feature_names].mean() if feature_names else None    if feature_names:        X = train[feature_names].to_numpy(dtype=float)        X_centered = X - np.column_stack([ids.map(x_means[c]).to_numpy() for c in feature_names])        y_centered = y - ids.map(y_mean).to_numpy()        beta, _, rank, _ = np.linalg.lstsq(X_centered, y_centered, rcond=None)        if rank < len(feature_names):            raise RuntimeError('Model design is rank deficient.')    else:        beta = np.array([])    return beta, y_mean, x_meansdef predict(frame, model):    names, beta, ymeans, xmeans = model    base = frame.norad_id.map(ymeans).to_numpy(dtype=float)    if not names:        return base    X = frame[names].to_numpy(dtype=float)    means = np.column_stack([frame.norad_id.map(xmeans[c]).to_numpy(dtype=float) for c in names])    return base + (X - means) @ betadef score(true, pred):    return float(np.sqrt(np.mean((np.asarray(true) - np.asarray(pred)) ** 2)))def main():    data = prepare_data()    data['same_interaction'] = data.kp_centered * data.altitude_100km    data['lag_interaction'] = data.kp_lag_centered * data.altitude_100km    train = data[data.period == 'train'].copy()    test = data[data.period == 'test'].copy()    specs = {        'satellite_baseline': [],        'same_day_kp': ['kp_centered', 'same_interaction'],        'previous_day_kp': ['kp_lag_centered', 'lag_interaction'],        'same_and_previous_kp': ['kp_centered', 'same_interaction', 'kp_lag_centered', 'lag_interaction'],    }    results = []    models = {}    all_predictions = []    for name, features in specs.items():        beta, ymeans, xmeans = fit_fixed_effects(train, features)        model = (features, beta, ymeans, xmeans)        models[name] = model        pred_train = predict(train, model)        pred_test = predict(test, model)        results.append({            'model': name, 'train_rmse_km_day': score(train.decay_km_day, pred_train),            'test_rmse_km_day': score(test.decay_km_day, pred_test),            'n_train': len(train), 'n_test': len(test), 'n_satellites': data.norad_id.nunique()        })        pred_table = test[['norad_id', 'date', 'reference_altitude_km', 'decay_km_day', 'daily_max_kp']].copy()        pred_table['model'] = name        pred_table['predicted_decay_km_day'] = pred_test        all_predictions.append(pred_table)    table = pd.DataFrame(results).sort_values('test_rmse_km_day')    table.to_csv(MODEL_CSV, index=False)    pd.concat(all_predictions).to_csv(PRED_CSV, index=False)    print('\nModel comparison (lower TEST RMSE = better held-out fit):')    print(table.to_string(index=False, float_format=lambda x: f'{x:.5f}'))    # Report both same-day and lag models; fitted coefficients are exploratory.    rows = []    for model_name, kp_feature, interaction in [        ('same_day_kp', 'kp_centered', 'same_interaction'),        ('previous_day_kp', 'kp_lag_centered', 'lag_interaction'),    ]:        features, beta, _, _ = models[model_name]        b_kp = float(beta[features.index(kp_feature)])        b_int = float(beta[features.index(interaction)])        print(f'\n{model_name}: estimated Δdecay per +1 Kp at 550 km = {b_kp:.6f} km/day')        print(f'Change in Kp slope per +100 km altitude = {b_int:.6f} km/day per Kp')        for altitude in (400, 475, 550, 625, 700, 775):            rows.append({'model': model_name, 'altitude_km': altitude,                         'decay_change_per_one_kp_km_day': b_kp + b_int*(altitude-550)/100})    slopes = pd.DataFrame(rows)    slopes.to_csv(SLOPES_CSV, index=False)    fig, ax = plt.subplots(figsize=(9, 5))    for model_name, group in slopes.groupby('model'):        ax.plot(group.altitude_km, 1000 * group.decay_change_per_one_kp_km_day,                marker='o', label=model_name.replace('_', ' '))    ax.axhline(0, color='gray', linestyle='--', linewidth=1)    ax.set(xlabel='Reference altitude (km)', ylabel='Fitted change in decay per +1 Kp (m/day)',           title='Exploratory Kp–decay slope by orbital altitude')    ax.grid(alpha=.3)    ax.legend()    fig.tight_layout()    fig.savefig(FIGURE, dpi=250)    plt.close(fig)    print(f'\nSaved: {MODEL_CSV}\nSaved: {SLOPES_CSV}\nSaved: {PRED_CSV}\nSaved: {FIGURE}')    print('\nLimitations: one storm window; Kp shared across satellites; GP-derived altitude;')    print('screening thresholds are heuristics; no causal interpretation or valid p-values.')if __name__ == '__main__':    main()